-- 장비 **라인업 마스터** — 라인업 → 모델 → 구성 (2026-11-26)
--
-- ── 왜 ───────────────────────────────────────────────────────────────────
--   장비를 등록할 때 라인업·모델·옵션을 **손으로 적는다**. 그래서 같은 기종이
--   「SURFCOM NEX 040」·「surfcom nex040」·「NEX 040」으로 갈려 쌓였다(1,447대 대조는
--   docs/equipment-master-match-20261126.md). 고를 수 있는 **정본 목록**을 둔다.
--
--   값은 가격표(price_list)의 **CMM Main body · SFG Main** 두 시트에서 뽑았다.
--   원문 1,229줄 → 품명(중복 뺀) **594개** → 라인업/모델/구성으로 갈랐다.
--   가르는 규칙과 전량 표는 docs/equipment-master-seed-20261126.md 에 있다.
--
-- ── 못 가른 줄도 넣는다 ──────────────────────────────────────────────────
--   품명은 사람이 적은 글이라 모양이 여럿이다. 규칙으로 **가장 그럴듯하게** 넣고
--   `pending = true` 로 표시해 둔다 — 화면에서는 똑같이 고를 수 있고, 나중에 사람이
--   고치면 된다. 빼 두면 그 기종은 영영 목록에 없다.
--
-- ── 20(반도체)은 시드가 없다 ─────────────────────────────────────────────
--   가격표의 두 시트가 전부 80(계측)이다. 20 라인업은 **자유 입력**으로 받고(화면),
--   쓰이는 이름이 쌓이면 그때 목록으로 올린다.
--
-- 재실행 안전 — create if not exists · on conflict do nothing.


-- ════════════════════════════════════════════════════════════════
-- [1단계] 표
-- ════════════════════════════════════════════════════════════════

create table if not exists public.equipment_lineups (
  id          bigserial primary key,
  name        text not null,
  -- '80' 계측 · '20' 반도체. 사업부 구분과 같은 값이다.
  line        text not null default '80' check (line in ('80', '20')),
  brand       text,
  series      text,
  active      boolean not null default true,
  -- 가격표에서 자동으로 가른 줄 가운데 **사람 확인이 남은 것**.
  pending     boolean not null default false,
  sort        integer not null default 0,
  created_at  timestamptz not null default now()
);
create unique index if not exists equipment_lineups_name_idx on public.equipment_lineups (name);

create table if not exists public.equipment_models (
  id          bigserial primary key,
  lineup_id   bigint not null references public.equipment_lineups(id) on delete cascade,
  name        text not null,
  active      boolean not null default true,
  pending     boolean not null default false,
  sort        integer not null default 0,
  created_at  timestamptz not null default now()
);
create unique index if not exists equipment_models_key_idx on public.equipment_models (lineup_id, name);

create table if not exists public.equipment_configs (
  id          bigserial primary key,
  model_id    bigint not null references public.equipment_models(id) on delete cascade,
  name        text not null,
  active      boolean not null default true,
  pending     boolean not null default false,
  sort        integer not null default 0,
  created_at  timestamptz not null default now()
);
create unique index if not exists equipment_configs_key_idx on public.equipment_configs (model_id, name);

comment on table public.equipment_lineups is '장비 라인업(브랜드+시리즈) 정본. 장비 등록 폼이 고른다.';
comment on column public.equipment_lineups.pending is '가격표에서 자동으로 가른 줄 — 사람 확인이 남았다.';


-- ════════════════════════════════════════════════════════════════
-- [2단계] RLS — 읽기는 전원, 쓰기는 관리 메뉴
-- ════════════════════════════════════════════════════════════════
--
-- 읽기를 전원에게 여는 까닭: 장비 등록 폼이 이 목록으로 고른다(로그인한 사람 전부).
-- 쓰기는 화면이 없다(D4 는 리뉴얼 뒤) — service role 라우트만 쓰도록 **정책을 두지
-- 않는다**. RLS 를 켜고 읽기 정책만 두면 그 밖의 쓰기는 막힌다.

alter table public.equipment_lineups enable row level security;
alter table public.equipment_models  enable row level security;
alter table public.equipment_configs enable row level security;

drop policy if exists equipment_lineups_select on public.equipment_lineups;
drop policy if exists equipment_models_select  on public.equipment_models;
drop policy if exists equipment_configs_select on public.equipment_configs;

create policy equipment_lineups_select on public.equipment_lineups for select to authenticated using (true);
create policy equipment_models_select  on public.equipment_models  for select to authenticated using (true);
create policy equipment_configs_select on public.equipment_configs for select to authenticated using (true);

grant select on table public.equipment_lineups to authenticated;
grant select on table public.equipment_models  to authenticated;
grant select on table public.equipment_configs to authenticated;


-- ════════════════════════════════════════════════════════════════
-- [3단계] 장비 줄의 **마스터 밖 표시**
-- ════════════════════════════════════════════════════════════════
--
-- 목록에 없는 이름을 자유 입력으로 받으면 그 줄에 자국을 남긴다 — 나중에 「마스터에
-- 없는 장비」만 모아 볼 수 있다. 칸이 없어도 화면은 돈다(라우트가 42703 이면 뺀다).

alter table public.devices
  add column if not exists master_pending boolean not null default false;

comment on column public.devices.master_pending is '라인업·모델·구성을 마스터 밖 값으로 적었다(자유 입력).';


